   280→/**
   281→ * Using the elevate system.
   282→ * Automatic contrast adjustment.
   283→ *
   284→ * <element className="hover-elevate" />
   285→ * <element className="active-elevate-2" />
   286→ *
   287→ * // Using the tailwind utility when a data attribute is "on"
   288→ * <element className="toggle-elevate data-[state=on]:toggle-elevated" />
   289→ * // Or manually controlling the toggle state
   290→ * <element className="toggle-elevate toggle-elevated" />
   291→ *
   292→ * Elevation systems have to handle many states.
   293→ * - not-hovered, vs. hovered vs. active  (three mutually exclusive states)
   294→ * - toggled or not
   295→ * - focused or not (this is not handled with these utilities)
   296→ *
   297→ * Even without handling focused or not, this is six possible combinations that
   298→ * need to be distinguished from eachother visually.
   299→ */
   300→@layer utilities {
   301→
   302→  /* Hide ugly search cancel button in Chrome until we can style it properly */
   303→  input[type="search"]::-webkit-search-cancel-button {
   304→    @apply hidden;
   305→  }
   306→
   307→  /* Placeholder styling for contentEditable div */
   308→  [contenteditable][data-placeholder]:empty::before {
   309→    content: attr(data-placeholder);
   310→    color: hsl(var(--muted-foreground));
   311→    pointer-events: none;
   312→  }
   313→
   314→  /* .no-default-hover-elevate/no-default-active-elevate is an escape hatch so consumers of
   315→   * buttons/badges can remove the automatic brightness adjustment on interactions
   316→   * and program their own. */
   317→  .no-default-hover-elevate {}
   318→
   319→  .no-default-active-elevate {}
   320→
   321→
   322→  /**
   323→   * Toggleable backgrounds go behind the content. Hoverable/active goes on top.
   324→   * This way they can stack/compound. Both will overlap the parent's borders!
   325→   * So borders will be automatically adjusted both on toggle, and hover/active,
   326→   * and they will be compounded.
   327→   */
   328→  .toggle-elevate::before,
   329→  .toggle-elevate-2::before {
   330→    content: "";
   331→    pointer-events: none;
   332→    position: absolute;
   333→    inset: 0px;
   334→    /*border-radius: inherit;   match rounded corners */
   335→    border-radius: inherit;
   336→    z-index: -1;
   337→    /* sits behind content but above backdrop */
   338→  }
   339→
   340→  .toggle-elevate.toggle-elevated::before {
   341→    background-color: var(--elevate-2);
   342→  }
   343→
   344→  /* If there's a 1px border, adjust the inset so that it covers that parent's border */
   345→  .border.toggle-elevate::before {
   346→    inset: -1px;
   347→  }
   348→
   349→  /* Does not work on elements with overflow:hidden! */
   350→  .hover-elevate:not(.no-default-hover-elevate),
   351→  .active-elevate:not(.no-default-active-elevate),
   352→  .hover-elevate-2:not(.no-default-hover-elevate),
   353→  .active-elevate-2:not(.no-default-active-elevate) {
   354→    position: relative;
   355→    z-index: 0;
   356→  }
   357→
   358→  .hover-elevate:not(.no-default-hover-elevate)::after,
   359→  .active-elevate:not(.no-default-active-elevate)::after,
   360→  .hover-elevate-2:not(.no-default-hover-elevate)::after,
   361→  .active-elevate-2:not(.no-default-active-elevate)::after {
   362→    content: "";
   363→    pointer-events: none;
   364→    position: absolute;
   365→    inset: 0px;
   366→    /*border-radius: inherit;   match rounded corners */
   367→    border-radius: inherit;
   368→    z-index: 999;
   369→    /* sits in front of content */
   370→  }
   371→
   372→  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
   373→  .active-elevate:active:not(.no-default-active-elevate)::after {
   374→    background-color: var(--elevate-1);
   375→  }
   376→
