          </Link>
          <div className="flex items-center px-4 py-2 rounded-md text-sm font-medium text-destructive/80 hover:bg-destructive/10 hover:text-destructive cursor-pointer">
            <LogOut className="h-5 w-5 mr-3" />
            Logout
          </div>
        </div>
      </aside>

      {/* Mobile Overlay */}
      {sidebarOpen && (
        <div 
          className="fixed inset-0 bg-black/20 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-card/50 backdrop-blur-sm border-b border-border sticky top-0 z-30 flex items-center justify-between px-6">
          <Button 
            variant="ghost" 
            size="icon" 
            className="lg:hidden mr-2"
            onClick={() => setSidebarOpen(!sidebarOpen)}
          >
            <Menu className="h-5 w-5" />
          </Button>

          <div className="flex items-center ml-auto space-x-4">
            <div className="flex items-center">
              <div className="h-2 w-2 rounded-full bg-green-500 mr-2 animate-pulse"></div>
              <span className="text-sm text-muted-foreground hidden sm:inline-block">System Online</span>
            </div>
