import type { Express } from "express";
import { createServer, type Server } from "http";
import { storage } from "./storage";
import { insertPatientSchema, insertDoctorSchema, insertAppointmentSchema } from "@shared/schema";
import { fromZodError } from "zod-validation-error";

export async function registerRoutes(
  httpServer: Server,
  app: Express
): Promise<Server> {

  app.get("/api/patients", async (req, res) => {
    try {
      const patients = await storage.getPatients();
      res.json(patients);
    } catch (error) {
      console.error("Error fetching patients:", error);
      res.status(500).json({ error: "Failed to fetch patients" });
    }
  });

  app.get("/api/patients/:id", async (req, res) => {
    try {
      const patient = await storage.getPatient(req.params.id);
      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }
      res.json(patient);
    } catch (error) {
      console.error("Error fetching patient:", error);
      res.status(500).json({ error: "Failed to fetch patient" });
    }
  });

  app.post("/api/patients", async (req, res) => {
    try {
      const result = insertPatientSchema.safeParse(req.body);
      if (!result.success) {
        return res.status(400).json({ error: fromZodError(result.error).toString() });
      }
      const patient = await storage.createPatient(result.data);
      res.status(201).json(patient);
    } catch (error) {
      console.error("Error creating patient:", error);
      res.status(500).json({ error: "Failed to create patient" });
    }
  });

  app.patch("/api/patients/:id", async (req, res) => {
    try {
      const patient = await storage.updatePatient(req.params.id, req.body);
      if (!patient) {
        return res.status(404).json({ error: "Patient not found" });
      }
      res.json(patient);
    } catch (error) {
      console.error("Error updating patient:", error);
      res.status(500).json({ error: "Failed to update patient" });
    }
  });

  app.delete("/api/patients/:id", async (req, res) => {
    try {
      const success = await storage.deletePatient(req.params.id);
      if (!success) {
        return res.status(404).json({ error: "Patient not found" });
      }
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting patient:", error);
      res.status(500).json({ error: "Failed to delete patient" });
    }
  });

  app.get("/api/doctors", async (req, res) => {
    try {
      const doctors = await storage.getDoctors();
      res.json(doctors);
    } catch (error) {
      console.error("Error fetching doctors:", error);
      res.status(500).json({ error: "Failed to fetch doctors" });
    }
  });

  app.post("/api/doctors", async (req, res) => {
    try {
      const result = insertDoctorSchema.safeParse(req.body);
      if (!result.success) {
        return res.status(400).json({ error: fromZodError(result.error).toString() });
      }
      const doctor = await storage.createDoctor(result.data);
      res.status(201).json(doctor);
    } catch (error) {
      console.error("Error creating doctor:", error);
      res.status(500).json({ error: "Failed to create doctor" });
    }
  });

  app.get("/api/appointments", async (req, res) => {
    try {
      const { date } = req.query;
      let appointments;

      if (date && typeof date === "string") {
        appointments = await storage.getAppointmentsByDate(new Date(date));
      } else {
        appointments = await storage.getAppointments();
      }

      res.json(appointments);
    } catch (error) {
      console.error("Error fetching appointments:", error);
      res.status(500).json({ error: "Failed to fetch appointments" });
    }
  });

  app.post("/api/appointments", async (req, res) => {
    try {
      const result = insertAppointmentSchema.safeParse(req.body);
      if (!result.success) {
        return res.status(400).json({ error: fromZodError(result.error).toString() });
      }
      const appointment = await storage.createAppointment(result.data);
      res.status(201).json(appointment);
    } catch (error) {
      console.error("Error creating appointment:", error);
      res.status(500).json({ error: "Failed to create appointment" });
    }
  });

  app.patch("/api/appointments/:id", async (req, res) => {
    try {
      const appointment = await storage.updateAppointment(req.params.id, req.body);
      if (!appointment) {
        return res.status(404).json({ error: "Appointment not found" });
      }
      res.json(appointment);
    } catch (error) {
      console.error("Error updating appointment:", error);
      res.status(500).json({ error: "Failed to update appointment" });
    }
  });

  app.delete("/api/appointments/:id", async (req, res) => {
    try {
      const success = await storage.deleteAppointment(req.params.id);
      if (!success) {
        return res.status(404).json({ error: "Appointment not found" });
      }
      res.status(204).send();
    } catch (error) {
      console.error("Error deleting appointment:", error);
      res.status(500).json({ error: "Failed to delete appointment" });
    }
  });

  app.get("/api/dashboard/stats", async (req, res) => {
    try {
      const stats = await storage.getDashboardStats();
      res.json(stats);
    } catch (error) {
      console.error("Error fetching dashboard stats:", error);
      res.status(500).json({ error: "Failed to fetch dashboard stats" });
    }
  });

  return httpServer;
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import type { Patient, InsertPatient, Doctor, InsertDoctor, Appointment, InsertAppointment } from "@shared/schema";

const API_BASE = "/api";

async function fetchJson<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...options?.headers,
    },
  });

  if (!response.ok) {
    throw new Error(`API error: ${response.statusText}`);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return response.json();
}

export function usePatients() {
  return useQuery<Patient[]>({
    queryKey: ["patients"],
    queryFn: () => fetchJson(`${API_BASE}/patients`),
  });
}

export function usePatient(id: string) {
  return useQuery<Patient>({
    queryKey: ["patients", id],
    queryFn: () => fetchJson(`${API_BASE}/patients/${id}`),
    enabled: !!id,
  });
}

export function useCreatePatient() {
  const queryClient = useQueryClient();
  return useMutation<Patient, Error, InsertPatient>({
    mutationFn: (data) => fetchJson(`${API_BASE}/patients`, {
      method: "POST",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });
}

export function useUpdatePatient() {
  const queryClient = useQueryClient();
  return useMutation<Patient, Error, { id: string; data: Partial<InsertPatient> }>({
    mutationFn: ({ id, data }) => fetchJson(`${API_BASE}/patients/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });
}

export function useDeletePatient() {
  const queryClient = useQueryClient();
  return useMutation<void, Error, string>({
    mutationFn: (id) => fetchJson(`${API_BASE}/patients/${id}`, {
      method: "DELETE",
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["patients"] });
    },
  });
}

export function useDoctors() {
  return useQuery<Doctor[]>({
    queryKey: ["doctors"],
    queryFn: () => fetchJson(`${API_BASE}/doctors`),
  });
}

export function useCreateDoctor() {
  const queryClient = useQueryClient();
  return useMutation<Doctor, Error, InsertDoctor>({
    mutationFn: (data) => fetchJson(`${API_BASE}/doctors`, {
      method: "POST",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["doctors"] });
    },
  });
}

export function useAppointments(date?: string) {
  return useQuery<(Appointment & { patientName?: string; doctorName?: string })[]>({
    queryKey: ["appointments", date],
    queryFn: () => {
      const url = date 
        ? `${API_BASE}/appointments?date=${date}`
        : `${API_BASE}/appointments`;
      return fetchJson(url);
    },
  });
}

export function useCreateAppointment() {
  const queryClient = useQueryClient();
  return useMutation<Appointment, Error, InsertAppointment>({
    mutationFn: (data) => fetchJson(`${API_BASE}/appointments`, {
      method: "POST",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["appointments"] });
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
    },
  });
}

export function useUpdateAppointment() {
  const queryClient = useQueryClient();
  return useMutation<Appointment, Error, { id: string; data: Partial<InsertAppointment> }>({
    mutationFn: ({ id, data }) => fetchJson(`${API_BASE}/appointments/${id}`, {
      method: "PATCH",
      body: JSON.stringify(data),
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["appointments"] });
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
    },
  });
}

export function useDeleteAppointment() {
  const queryClient = useQueryClient();
  return useMutation<void, Error, string>({
    mutationFn: (id) => fetchJson(`${API_BASE}/appointments/${id}`, {
      method: "DELETE",
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["appointments"] });
      queryClient.invalidateQueries({ queryKey: ["dashboard"] });
    },
  });
}

export function useDashboardStats() {
  return useQuery<{
    totalPatients: number;
    todayAppointments: number;
    completedAppointments: number;
    monthlyRevenue: string;
  }>({
    queryKey: ["dashboard", "stats"],
    queryFn: () => fetchJson(`${API_BASE}/dashboard/stats`),
  });
}

import Layout from "@/components/layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Search, Plus, Filter, MoreHorizontal } from "lucide-react";
import { usePatients } from "@/hooks/use-api";
import { format } from "date-fns";
import { useState } from "react";

export default function Patients() {
  const { data: patients = [], isLoading } = usePatients();
  const [searchQuery, setSearchQuery] = useState("");

  const filteredPatients = patients.filter(patient => 
    patient.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    patient.patientId.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <Layout>
      <div className="flex flex-col gap-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground">Patients</h1>
            <p className="text-muted-foreground">Manage patient records and history.</p>
          </div>
          <Button className="gap-2 shadow-md">
            <Plus className="h-4 w-4" /> Add Patient
          </Button>
        </div>

        <div className="bg-card rounded-lg border border-border shadow-sm overflow-hidden">
          <div className="p-4 border-b border-border flex gap-4">
            <div className="relative flex-1 max-w-sm">
              <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search by name, ID or phone..." 
                className="pl-8" 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            <Button variant="outline" className="gap-2">
              <Filter className="h-4 w-4" /> Filter
            </Button>
          </div>

          {isLoading ? (
            <div className="p-8 text-center text-muted-foreground">Loading patients...</div>
          ) : filteredPatients.length === 0 ? (
            <div className="p-8 text-center text-muted-foreground">
              {searchQuery ? "No patients found matching your search." : "No patients yet. Add your first patient to get started."}
            </div>
          ) : (
            <>
              <Table>
                <TableHeader className="bg-muted/40">
                  <TableRow>
                    <TableHead className="w-[100px]">ID</TableHead>
                    <TableHead>Patient Name</TableHead>
                    <TableHead>Age/Gender</TableHead>
                    <TableHead>Last Visit</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Outstanding</TableHead>
                    <TableHead className="w-[50px]"></TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredPatients.map((patient) => (
                    <TableRow key={patient.id} className="hover:bg-muted/5 cursor-pointer">
                      <TableCell className="font-medium text-muted-foreground">{patient.patientId}</TableCell>
                      <TableCell>
                        <div className="flex items-center gap-3">
                          <Avatar className="h-8 w-8 bg-primary/10 text-primary border border-primary/10">
                            <AvatarFallback className="bg-transparent">{patient.name.split(' ').map(n=>n[0]).join('')}</AvatarFallback>
                          </Avatar>
                          <span className="font-medium">{patient.name}</span>
                        </div>
                      </TableCell>
                      <TableCell className="text-muted-foreground">{patient.age} / {patient.gender}</TableCell>
                      <TableCell>{patient.lastVisit ? format(new Date(patient.lastVisit), "yyyy-MM-dd") : "Never"}</TableCell>
                      <TableCell>
                        {patient.status === "Active" && <Badge variant="outline" className="bg-green-50 text-green-700 border-green-200 hover:bg-green-100">Active</Badge>}
                        {patient.status === "Treatment" && <Badge variant="outline" className="bg-blue-50 text-blue-700 border-blue-200 hover:bg-blue-100">Treatment</Badge>}
                        {patient.status === "Inactive" && <Badge variant="outline" className="bg-gray-50 text-gray-700 border-gray-200 hover:bg-gray-100">Inactive</Badge>}
                      </TableCell>
                      <TableCell className={`text-right font-medium ${patient.balance !== "0.00" ? "text-red-600" : "text-muted-foreground"}`}>
                        ${patient.balance}
                      </TableCell>
                      <TableCell>
                        <Button variant="ghost" size="icon" className="h-8 w-8 text-muted-foreground">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>

              <div className="p-4 border-t border-border bg-muted/20 text-xs text-muted-foreground text-center">
                Showing {filteredPatients.length} of {patients.length} patients
              </div>
            </>
          )}
        </div>
      </div>
    </Layout>
  );
}

import Layout from "@/components/layout";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ChevronLeft, ChevronRight, Plus, Search, Clock } from "lucide-react";
import { cn } from "@/lib/utils";
import { useAppointments, useDoctors } from "@/hooks/use-api";
import { useState } from "react";
import { format, addDays, subDays } from "date-fns";

const timeSlots = [
  "08:00 AM", "09:00 AM", "10:00 AM", "11:00 AM", "12:00 PM", 
  "01:00 PM", "02:00 PM", "03:00 PM", "04:00 PM", "05:00 PM"
];

const getColorForType = (type: string) => {
  const colors: Record<string, string> = {
    "General Checkup": "bg-blue-100 border-blue-300 text-blue-700",
    "Root Canal": "bg-orange-100 border-orange-300 text-orange-700",
    "Teeth Whitening": "bg-purple-100 border-purple-300 text-purple-700",
    "Whitening": "bg-purple-100 border-purple-300 text-purple-700",
    "Extraction": "bg-red-100 border-red-300 text-red-700",
    "Consultation": "bg-green-100 border-green-300 text-green-700",
    "Follow-up": "bg-teal-100 border-teal-300 text-teal-700",
  };
  return colors[type] || "bg-gray-100 border-gray-300 text-gray-700";
};

export default function Appointments() {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const dateString = format(selectedDate, "yyyy-MM-dd");

  const { data: appointments = [], isLoading } = useAppointments(dateString);
  const { data: doctors = [] } = useDoctors();

  const goToPreviousDay = () => setSelectedDate(subDays(selectedDate, 1));
  const goToNextDay = () => setSelectedDate(addDays(selectedDate, 1));

  return (
    <Layout>
      <div className="flex flex-col h-[calc(100vh-8rem)] gap-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground">Schedule</h1>
            <p className="text-muted-foreground">Manage appointments and bookings.</p>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={goToPreviousDay}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <div className="text-sm font-medium px-2 min-w-[120px] text-center">
              {format(selectedDate, "MMM dd, yyyy")}
            </div>
            <Button variant="outline" size="icon" onClick={goToNextDay}>
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button className="ml-2 gap-2 shadow-md">
              <Plus className="h-4 w-4" /> New Appointment
            </Button>
          </div>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-4 bg-card p-4 rounded-lg border border-border shadow-sm">
          <div className="relative flex-1 max-w-xs">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Search patient..." className="pl-8 bg-background" />
          </div>
          <Select defaultValue="all">
            <SelectTrigger className="w-[180px] bg-background">
              <SelectValue placeholder="Filter by Doctor" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Doctors</SelectItem>
              {doctors.map(d => <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {/* Calendar Grid */}
        <div className="flex-1 bg-card rounded-lg border border-border shadow-sm overflow-hidden flex flex-col">
          {isLoading ? (
            <div className="flex-1 flex items-center justify-center text-muted-foreground">
              Loading appointments...
            </div>
          ) : doctors.length === 0 ? (
            <div className="flex-1 flex items-center justify-center text-muted-foreground">
              No doctors available. Please add doctors first.
            </div>
          ) : (
            <>
              {/* Header Row */}
              <div className="flex border-b border-border bg-muted/30">
                <div className="w-20 p-4 border-r border-border text-xs font-medium text-muted-foreground flex items-center justify-center">
                  Time
                </div>
                {doctors.map(doctor => (
                  <div key={doctor.id} className="flex-1 p-4 text-sm font-semibold text-center border-r border-border last:border-r-0">
                    {doctor.name}
                  </div>
                ))}
              </div>

              {/* Time Slots */}
              <div className="flex-1 overflow-y-auto">
                {timeSlots.map((time) => (
                  <div key={time} className="flex border-b border-border min-h-[100px] group hover:bg-muted/5">
                    {/* Time Column */}
                    <div className="w-20 p-2 border-r border-border text-xs text-muted-foreground flex justify-center pt-3 bg-muted/10">
                      {time}
                    </div>

                    {/* Doctor Columns */}
                    {doctors.map(doctor => {
                      const apt = appointments.find(a => {
                        const aptTime = format(new Date(a.appointmentDate), "hh:mm a");
                        return a.doctorId === doctor.id && aptTime === time;
                      });

                      return (
                        <div key={`${doctor.id}-${time}`} className="flex-1 p-1 border-r border-border last:border-r-0 relative">
                          {apt ? (
                            <div className={cn(
                              "h-full w-full rounded-md p-3 text-xs border-l-4 shadow-sm cursor-pointer hover:brightness-95 transition-all",
                              getColorForType(apt.type)
                            )}>
                              <div className="font-bold text-sm mb-1">{apt.patientName || 'Unknown'}</div>
                              <div className="opacity-90 mb-1">{apt.type}</div>
                              <div className="flex items-center opacity-75 mt-2">
                                <Clock className="h-3 w-3 mr-1" /> {apt.duration} min
                              </div>
                            </div>
                          ) : (
                            <div className="h-full w-full opacity-0 group-hover:opacity-100 hover:bg-primary/5 transition-all flex items-center justify-center cursor-pointer rounded-md border-2 border-dashed border-transparent hover:border-primary/20">
                              <Plus className="h-4 w-4 text-primary/40" />
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </Layout>
  );
}

