    "Consultation": "bg-green-100 border-green-300 text-green-700",
    "Follow-up": "bg-teal-100 border-teal-300 text-teal-700",
  };
  return colors[type] || "bg-gray-100 border-gray-300 text-gray-700";
};

export default function Appointments() {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const dateString = format(selectedDate, "yyyy-MM-dd");
  const [isOpen, setIsOpen] = useState(false);
  const [formData, setFormData] = useState({
    patientId: "",
    doctorId: "",
    time: "09:00 AM",
    duration: "45",
    type: "General Checkup",
    status: "Scheduled",
    notes: "",
  });

  const { data: appointments = [], isLoading } = useAppointments(dateString);
  const { data: doctors = [] } = useDoctors();
  const { data: patients = [] } = usePatients();
  const createAppointment = useCreateAppointment();

  const goToPreviousDay = () => setSelectedDate(subDays(selectedDate, 1));
  const goToNextDay = () => setSelectedDate(addDays(selectedDate, 1));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const time = parse(formData.time, "hh:mm a", selectedDate);
      await createAppointment.mutateAsync({
        patientId: formData.patientId,
        doctorId: formData.doctorId,
        appointmentDate: time,
        duration: Number(formData.duration),
        type: formData.type,
        status: formData.status,
        notes: formData.notes || null,
      });
      toast.success("Appointment created successfully");
      setIsOpen(false);
      setFormData({
        patientId: "",
        doctorId: "",
        time: "09:00 AM",
        duration: "45",
        type: "General Checkup",
        status: "Scheduled",
        notes: "",
      });
    } catch {
      toast.error("Failed to create appointment");
    }
  };

  return (
    <Layout>
      <div className="flex flex-col h-[calc(100vh-8rem)] gap-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground">Schedule</h1>
            <p className="text-muted-foreground">Manage appointments and bookings.</p>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="icon" onClick={goToPreviousDay}>
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <div className="text-sm font-medium px-2 min-w-[120px] text-center">
              {format(selectedDate, "MMM dd, yyyy")}
            </div>
            <Button variant="outline" size="icon" onClick={goToNextDay}>
              <ChevronRight className="h-4 w-4" />
            </Button>
            <Button className="ml-2 gap-2 shadow-md" onClick={() => setIsOpen(true)}>
              <Plus className="h-4 w-4" /> New Appointment
            </Button>
          </div>
        </div>

        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogContent className="sm:max-w-[500px] max-h-[90vh] overflow-y-auto">
