function StatCard({ 
  title, 
  value, 
  subtitle, 
  icon: Icon, 
  trend,
  trendValue,
  color,
  loading 
}: { 
  title: string; 
  value: string | number; 
  subtitle: string; 
  icon: React.ElementType; 
  trend?: "up" | "down";
  trendValue?: string;
  color: string;
  loading?: boolean;
}) {
  if (loading) {
    return (
      <Card className="card-premium stat-card overflow-hidden">
        <CardContent className="p-6">
          <Skeleton className="h-4 w-24 mb-4" />
          <Skeleton className="h-8 w-16 mb-2" />
          <Skeleton className="h-3 w-32" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="card-premium stat-card overflow-hidden group">
      <CardContent className="p-6">
        <div className="flex items-start justify-between">
          <div className="space-y-3">
            <p className="text-sm font-medium text-muted-foreground">{title}</p>
            <div className="text-3xl font-bold tracking-tight text-foreground">{value}</div>
            <div className="flex items-center gap-2">
              {trend && (
                <span className={cn(
                  "inline-flex items-center text-xs font-medium px-2 py-0.5 rounded-full",
                  trend === "up" ? "bg-green-50 text-green-700" : "bg-red-50 text-red-700"
                )}>
                  {trend === "up" ? <TrendingUp className="h-3 w-3 mr-1" /> : <TrendingDown className="h-3 w-3 mr-1" />}
                  {trendValue}
                </span>
              )}
              <span className="text-xs text-muted-foreground">{subtitle}</span>
            </div>
          </div>
          <div className={cn(
            "h-11 w-11 rounded-xl flex items-center justify-center transition-transform duration-300 group-hover:scale-110",
            color
          )}>
            <Icon className="h-5 w-5" />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

