import Layout from "@/components/layout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { ChevronLeft, ChevronRight, Plus, Search, Clock, X, CalendarDays } from "lucide-react";
import { cn } from "@/lib/utils";
import { useAppointments, useDoctors, usePatients, useCreateAppointment } from "@/hooks/use-api";
import { useState } from "react";
import { format, addDays, subDays, parse } from "date-fns";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Skeleton } from "@/components/ui/skeleton";

const timeSlots = [
  "08:00 AM", "09:00 AM", "10:00 AM", "11:00 AM", "12:00 PM",
  "01:00 PM", "02:00 PM", "03:00 PM", "04:00 PM", "05:00 PM"
];

const getColorForType = (type: string) => {
  const colors: Record<string, string> = {
    "General Checkup": "bg-teal-50 border-teal-200 text-teal-800",
    "Root Canal": "bg-amber-50 border-amber-200 text-amber-800",
    "Teeth Whitening": "bg-violet-50 border-violet-200 text-violet-800",
    "Whitening": "bg-violet-50 border-violet-200 text-violet-800",
    "Extraction": "bg-rose-50 border-rose-200 text-rose-800",
    "Consultation": "bg-emerald-50 border-emerald-200 text-emerald-800",
    "Follow-up": "bg-cyan-50 border-cyan-200 text-cyan-800",
  };
  return colors[type] || "bg-slate-50 border-slate-200 text-slate-800";
};

export default function Appointments() {
  const [selectedDate, setSelectedDate] = useState(new Date());
  const dateString = format(selectedDate, "yyyy-MM-dd");
  const [isOpen, setIsOpen] = useState(false);
  const [formData, setFormData] = useState({
    patientId: "",
    doctorId: "",
    time: "09:00 AM",
    duration: "45",
    type: "General Checkup",
    status: "Scheduled",
    notes: "",
  });

  const { data: appointments = [], isLoading } = useAppointments(dateString);
  const { data: doctors = [] } = useDoctors();
  const { data: patients = [] } = usePatients();
  const createAppointment = useCreateAppointment();

  const goToPreviousDay = () => setSelectedDate(subDays(selectedDate, 1));
  const goToNextDay = () => setSelectedDate(addDays(selectedDate, 1));

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const time = parse(formData.time, "hh:mm a", selectedDate);
      await createAppointment.mutateAsync({
        patientId: formData.patientId,
        doctorId: formData.doctorId,
        appointmentDate: time,
        duration: Number(formData.duration),
        type: formData.type,
        status: formData.status,
        notes: formData.notes || null,
      });
      toast.success("Appointment created successfully");
      setIsOpen(false);
      setFormData({
        patientId: "",
        doctorId: "",
        time: "09:00 AM",
        duration: "45",
        type: "General Checkup",
        status: "Scheduled",
        notes: "",
      });
    } catch {
      toast.error("Failed to create appointment");
    }
  };

  const isToday = format(selectedDate, "yyyy-MM-dd") === format(new Date(), "yyyy-MM-dd");

  return (
    <Layout>
      <div className="flex flex-col h-[calc(100vh-8rem)] gap-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground">Schedule</h1>
            <p className="text-muted-foreground mt-1.5 text-sm">Manage appointments and bookings.</p>
          </div>
          <div className="flex items-center gap-2">
            <div className="flex items-center bg-card border border-border rounded-lg p-1 shadow-sm">
              <Button variant="ghost" size="icon" className="h-9 w-9" onClick={goToPreviousDay}>
                <ChevronLeft className="h-4 w-4" />
              </Button>
              <div className="flex items-center gap-2 px-3">
                <CalendarDays className="h-4 w-4 text-muted-foreground" />
                <div className="text-sm font-semibold min-w-[130px] text-center">
                  {format(selectedDate, "MMM dd, yyyy")}
                  {isToday && <span className="ml-2 text-xs text-primary font-medium">Today</span>}
                </div>
              </div>
              <Button variant="ghost" size="icon" className="h-9 w-9" onClick={goToNextDay}>
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
            <Button className="gap-2 shadow-sm hover:shadow-md transition-all" onClick={() => setIsOpen(true)}>
              <Plus className="h-4 w-4" /> New
            </Button>
          </div>
        </div>

        {/* New Appointment Dialog */}
        <Dialog open={isOpen} onOpenChange={setIsOpen}>
          <DialogContent className="sm:max-w-[520px] max-h-[90vh] overflow-y-auto p-0">
            <div className="p-6 pb-4 border-b border-border">
              <DialogHeader>
                <DialogTitle className="text-xl">New Appointment</DialogTitle>
              </DialogHeader>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-5">
              <div className="space-y-2">
                <Label className="text-sm font-medium">Patient</Label>
                <Select value={formData.patientId} onValueChange={(v) => setFormData({ ...formData, patientId: v })}>
                  <SelectTrigger className="h-10">
                    <SelectValue placeholder="Select patient" />
                  </SelectTrigger>
                  <SelectContent>
                    {patients.map(p => (
                      <SelectItem key={p.id} value={p.id}>{p.name} ({p.patientId})</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium">Doctor</Label>
                <Select value={formData.doctorId} onValueChange={(v) => setFormData({ ...formData, doctorId: v })}>
                  <SelectTrigger className="h-10">
                    <SelectValue placeholder="Select doctor" />
                  </SelectTrigger>
                  <SelectContent>
                    {doctors.map(d => (
                      <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Time</Label>
                  <Select value={formData.time} onValueChange={(v) => setFormData({ ...formData, time: v })}>
                    <SelectTrigger className="h-10">
                      <SelectValue placeholder="Select time" />
                    </SelectTrigger>
                    <SelectContent>
                      {timeSlots.map(t => <SelectItem key={t} value={t}>{t}</SelectItem>)}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Duration (min)</Label>
                  <Input type="number" value={formData.duration} onChange={(e) => setFormData({ ...formData, duration: e.target.value })} className="h-10" />
                </div>
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium">Type</Label>
                <Select value={formData.type} onValueChange={(v) => setFormData({ ...formData, type: v })}>
                  <SelectTrigger className="h-10">
                    <SelectValue placeholder="Select type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="General Checkup">General Checkup</SelectItem>
                    <SelectItem value="Root Canal">Root Canal</SelectItem>
                    <SelectItem value="Teeth Whitening">Teeth Whitening</SelectItem>
                    <SelectItem value="Extraction">Extraction</SelectItem>
                    <SelectItem value="Consultation">Consultation</SelectItem>
                    <SelectItem value="Follow-up">Follow-up</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label className="text-sm font-medium">Notes</Label>
                <Input value={formData.notes} onChange={(e) => setFormData({ ...formData, notes: e.target.value })} placeholder="Optional notes..." className="h-10" />
              </div>
              <DialogFooter className="gap-2 pt-2">
                <Button type="button" variant="outline" onClick={() => setIsOpen(false)} className="h-10">
                  <X className="h-4 w-4 mr-1" /> Cancel
                </Button>
                <Button type="submit" disabled={createAppointment.isPending} className="h-10">
                  {createAppointment.isPending ? "Booking..." : "Book Appointment"}
                </Button>
              </DialogFooter>
            </form>
          </DialogContent>
        </Dialog>

        {/* Filters */}
        <div className="flex items-center gap-3">
          <div className="relative flex-1 max-w-xs">
            <Search className="absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input placeholder="Search patient..." className="pl-10 h-10 bg-card" />
          </div>
          <Select defaultValue="all">
            <SelectTrigger className="w-[180px] h-10 bg-card">
              <SelectValue placeholder="Filter by Doctor" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Doctors</SelectItem>
              {doctors.map(d => <SelectItem key={d.id} value={d.id}>{d.name}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {/* Calendar Grid */}
        <div className="flex-1 bg-card rounded-xl border border-border shadow-sm overflow-hidden flex flex-col">
          {isLoading ? (
            <div className="flex-1 flex items-center justify-center">
              <div className="space-y-4 w-full p-6">
                <Skeleton className="h-8 w-full" />
                {[1,2,3,4].map(i => (
                  <div key={i} className="flex gap-4">
                    <Skeleton className="h-20 w-20 flex-shrink-0" />
                    <Skeleton className="h-20 flex-1" />
                    <Skeleton className="h-20 flex-1" />
                    <Skeleton className="h-20 flex-1" />
                  </div>
                ))}
              </div>
            </div>
          ) : doctors.length === 0 ? (
            <div className="flex-1 flex items-center justify-center">
              <div className="text-center">
                <div className="h-16 w-16 rounded-full bg-muted/50 flex items-center justify-center mx-auto mb-4">
                  <CalendarDays className="h-8 w-8 text-muted-foreground" />
                </div>
                <h3 className="text-lg font-semibold text-foreground mb-1">No doctors available</h3>
                <p className="text-sm text-muted-foreground">Please add doctors to start scheduling appointments.</p>
              </div>
            </div>
          ) : (
            <>
              {/* Header Row */}
              <div className="flex border-b border-border bg-muted/30">
                <div className="w-20 p-4 border-r border-border text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center justify-center">
                  Time
                </div>
                {doctors.map(doctor => (
                  <div key={doctor.id} className="flex-1 p-4 text-sm font-semibold text-center border-r border-border last:border-r-0">
                    {doctor.name}
                  </div>
                ))}
              </div>

              {/* Time Slots */}
              <div className="flex-1 overflow-y-auto">
                {timeSlots.map((time) => (
                  <div key={time} className="flex border-b border-border min-h-[100px] group hover:bg-muted/30 transition-colors">
                    {/* Time Column */}
                    <div className="w-20 p-3 border-r border-border text-xs font-medium text-muted-foreground flex justify-center pt-4 bg-muted/20">
                      {time}
                    </div>

                    {/* Doctor Columns */}
                    {doctors.map(doctor => {
                      const apt = appointments.find(a => {
                        const aptTime = format(new Date(a.appointmentDate), "hh:mm a");
                        return a.doctorId === doctor.id && aptTime === time;
                      });

                      return (
                        <div key={`${doctor.id}-${time}`} className="flex-1 p-1.5 border-r border-border last:border-r-0 relative">
                          {apt ? (
                            <div className={cn(
                              "h-full w-full rounded-lg p-3 text-xs border-l-[3px] shadow-sm cursor-pointer transition-all duration-200 hover:shadow-md hover:scale-[1.02]",
                              getColorForType(apt.type)
                            )}>
                              <div className="font-bold text-sm mb-1">{apt.patientName || 'Unknown'}</div>
                              <div className="opacity-80 mb-1 text-xs">{apt.type}</div>
                              <div className="flex items-center opacity-60 mt-2 text-xs">
                                <Clock className="h-3 w-3 mr-1" /> {apt.duration} min
                              </div>
                            </div>
                          ) : (
                            <div className="h-full w-full opacity-0 group-hover:opacity-100 hover:bg-primary/5 transition-all flex items-center justify-center cursor-pointer rounded-lg border-2 border-dashed border-transparent hover:border-primary/20">
                              <Plus className="h-4 w-4 text-primary/40" />
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      </div>
    </Layout>
  );
}
